import json
import sys
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone

BASE = "http://localhost:8080"
START = datetime(2025, 3, 1, tzinfo=timezone.utc)
END = datetime(2025, 6, 1, tzinfo=timezone.utc)  # exclusive: covers 31 May inclusive
OUT = "/workspace/result.json"
LOG = "/tmp/recon/log.txt"

token = None
log = open(LOG, "w")


def note(msg):
    log.write(msg + "\n")
    log.flush()


def get_token():
    global token
    req = urllib.request.Request(BASE + "/token", method="POST", data=b"")
    with urllib.request.urlopen(req, timeout=30) as r:
        token = json.load(r)["token"]
    note("token refreshed")


def request(path, auth=True, max_attempts=50):
    """GET path, honouring 429 waits, refreshing token on 401, retrying other failures."""
    attempt = 0
    while True:
        attempt += 1
        if attempt > max_attempts:
            raise RuntimeError(f"gave up on {path} after {max_attempts} attempts")
        headers = {}
        if auth:
            if token is None:
                get_token()
            headers["Authorization"] = "Bearer " + token
        req = urllib.request.Request(BASE + path, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return json.load(r)
        except urllib.error.HTTPError as e:
            body = e.read().decode("utf-8", "replace")
            if e.code == 404:
                return None
            if e.code == 401:
                note(f"401 on {path}; refreshing token")
                get_token()
                continue
            if e.code == 429:
                wait = e.headers.get("Retry-After")
                try:
                    wait = float(wait)
                except (TypeError, ValueError):
                    wait = None
                if wait is None:
                    try:
                        wait = float(json.loads(body).get("retry_after", 1))
                    except Exception:
                        wait = 1.0
                note(f"429 on {path}; body={body[:200]!r}; waiting {wait}s")
                time.sleep(wait)
                continue
            note(f"HTTP {e.code} on {path}: {body[:200]!r}; retrying")
            time.sleep(min(2 ** min(attempt, 6), 30))
        except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
            note(f"network error on {path}: {e}; retrying")
            time.sleep(min(2 ** min(attempt, 6), 30))


def parse_utc(ts):
    dt = datetime.fromisoformat(ts.replace("Z", "+00:00"))
    if dt.tzinfo is None:
        raise ValueError(f"naive timestamp: {ts}")
    return dt.astimezone(timezone.utc)


def discounted_cents(amount, pct):
    # amount * (100 - pct) / 100, rounded half up to whole cents, integer-only
    num = amount * (100 - pct)
    q, r = divmod(num, 100)
    if r * 2 >= 100:
        q += 1
    return q


def main():
    seen = {}  # order id -> order, first occurrence
    listings = 0
    page = 1
    total_pages = None
    while True:
        data = request(f"/orders?page={page}")
        if data is None:
            raise RuntimeError(f"orders page {page} returned 404")
        total_pages = data["total_pages"]
        items = data["items"]
        listings += len(items)
        for o in items:
            if o["id"] in seen:
                if seen[o["id"]] != o:
                    note(f"WARNING: duplicate id {o['id']} differs between listings")
                continue
            seen[o["id"]] = o
        note(f"page {page}/{total_pages}: {len(items)} items")
        if page >= total_pages or data.get("next") is None and page >= total_pages:
            break
        page += 1

    duplicates = listings - len(seen)

    customers = {}
    by_region = {"north": 0, "south": 0, "east": 0, "west": 0}
    total = 0
    count = 0
    status_counts = {}
    for o in seen.values():
        status_counts[o["status"]] = status_counts.get(o["status"], 0) + 1
        if o["status"] != "shipped":
            continue
        t = parse_utc(o["placed_at"])
        if not (START <= t < END):
            continue
        cid = o["customer_id"]
        if cid not in customers:
            c = request(f"/customers/{cid}")
            if c is None:
                raise RuntimeError(f"customer {cid} not found for order {o['id']}")
            customers[cid] = c
        c = customers[cid]
        amt = discounted_cents(o["amount_cents"], c["discount_pct"])
        by_region[c["region"]] += amt
        total += amt
        count += 1

    note(f"listings={listings} distinct={len(seen)} duplicates={duplicates}")
    note(f"status_counts={status_counts}")
    note(f"customers fetched={len(customers)}")

    result = {
        "total_cents": total,
        "order_count": count,
        "duplicates_skipped": duplicates,
        "by_region": by_region,
    }
    assert sum(by_region.values()) == total
    with open(OUT, "w") as f:
        json.dump(result, f, indent=2)
        f.write("\n")
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    sys.exit(main())

